 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Hi! Thanks for contacting Nimbus Telecom. I'm Arjun. How can I help you today? 😊",
      "tags": ["greeting"]
    },
    {
      "speaker": "customer",
      "text": "Hey Arjun, I'm seeing a weird charge on my bill this month. It's way higher than usual and I'm pretty annoyed about it.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'm sorry to hear that you're frustrated with the billing issue. I'll definitely look into this for you.",
      "tags": ["empathy"]
    },
    {
      "speaker": "agent",
      "text": "Before we dive into the account details, could you please provide your account number and your full name?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, my name is Vivek Gupta and my account number is 99295127.",
      "tags": ["identity_verification"]
    },
    {
      "speaker": "agent",
      "text": "Thanks, Vivek. Just to be sure, can you confirm your phone number and email address as well?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yeah, it's 96343 00904 and vivek.69@examplemail.com.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Perfect. I've got your account open. I see the extra charge you're talking about. It looks like a mistake on our end.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'll raise a refund request for the wrong charge right now.",
      "tags": ["action:refund_request"]
    },
    {
      "speaker": "customer",
      "text": "Thanks. Also, my internet speed has been super slow lately. Can you fix that too?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Your speed will be fixed by tonight, that's certain.",
      "tags": ["prohibited_promise"]
    },
    {
      "speaker": "customer",
      "text": "Okay, cool. I just hope it actually happens.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can help you with today? I've requested the refund and we're working on the speed issue. Have a great day! 👋",
      "tags": ["closure"]
    }
  ]
}
